  "daemon.shell_environment_timeout": "لم ينته {shell} -l -i -c '{command}' خلال {timeout}. ربما يعلق ملف بدء الصدفة بانتظار شيء غير stdin، أو ترك عملية خلفية تُبقي خرج الصدفة مفتوحاً. لن يبدأ {appName} ما دامت البيئة غير معروفة، لأنه لن يخمّنها. أصلح الخطوة البطيئة في ملفات rc للصدفة أو تجاوزها.",
  "daemon.shell_environment_timeout.sessionLaunchBlocked": "لم ينته {shell} -l -i -c '{command}' خلال {timeout}. ربما يعلق ملف بدء الصدفة بانتظار شيء غير stdin، أو ترك عملية خلفية تُبقي خرج الصدفة مفتوحاً. لا يمكن بدء الجلسات حتى تُقرأ بيئة صدفة تسجيل الدخول. أصلح الخطوة البطيئة في ملفات rc للصدفة أو تجاوزها.",
