  "daemon.agent_not_available": "{agent} غير متاح على هذا الجهاز: لم يُعثر على ملفه التنفيذي في {pathVar} لصدفة تسجيل الدخول. لفتح جلسة، تأكد من توفر أحد الوكلاء المدعومين التاليين في {pathVar}: {agents}.",
