  "daemon.queued_messages_dropped": "أسقط {appName} ما وضعه في طابور هذه الجلسة. قد يحتوي سطر الإدخال على جزء من رسالة تعذّر على التطبيق إكمال كتابتها، وستُدمج الرسالة التالية المكتوبة في الجلسة معه. افحص سطر إدخال الجلسة قبل إرسال أي شيء آخر.",
  "daemon.handoff_messages_dropped": "تعذر على {appName} إيصال رسائل حُجزت لجلسة أثناء تسليمها، لذا أُسقطت.",
  "daemon.sharing_messages_dropped": "أسقط {appName} رسائل حُجزت لجلسة أثناء تغيير مشاركة حسابها، لأن الجلسة لم يُعد تشغيلها.",
  "daemon.message_not_sent": "لم يرسل {agent} رسالة كتبها {appName} في هذه الجلسة، لذا تنتظر في مربع إدخالها. لا يكتب التطبيق شيئاً آخر في الجلسة حتى يُرسل طلب.",
  "daemon.message_acceptance_unconfirmed": "لم يؤكد {agent} استلام رسالة كتبها {appName} في هذه الجلسة. قد تكون الرسالة في الطابور بالفعل، ولن يرسلها التطبيق مجدداً. تُحجز الرسائل اللاحقة لثلاث ثوانٍ كحد أقصى أو حتى يُرسل طلب آخر. افحص المحادثة قبل أن تقرر إعادة إرسال الرسالة.",
  "daemon.message_not_sent.retry": "لم يؤكد {agent} إرسال رسالة كتبها {appName} في هذه الجلسة بعد. سيحاول التطبيق إرسال الإدخال الحالي مرة أخرى دون لصق الرسالة مجدداً. أجب عن أي مربع حوار معلّق أولاً.",
  "daemon.message_discarded_by_dialog": "عرض {agent} مربع حوار أثناء كتابة {appName} لرسالة في هذه الجلسة وتخلّص من الرسالة. سيكتبها التطبيق مجدداً بعد الإجابة عن الحوار.",
  "daemon.message_diverted_by_view": "كان {agent} يعرض وكلاءه في الخلفية أثناء كتابة {appName} لرسالة في هذه الجلسة، فذهبت الرسالة إلى ذلك العرض بدلاً من المحادثة. افحص الجلسة.",
  "daemon.submit_retry_failed": "لم يؤكد {agent} إرسال رسالة كتبها {appName} في هذه الجلسة، وتعذر على التطبيق الضغط على {enter} مجدداً. افحص مربع الإدخال. إذا ظلت الرسالة فيه، فاضغط {enter} دون لصقها مجدداً. السبب: {detail}",
  "daemon.draft_save_unconfirmed": "لم يؤكد {agent} حفظ المسودة في مربع إدخال هذه الجلسة، لذا كتب {appName} رسالته في المربع كما هو. افحص المحادثة: ربما أُرسلت الرسالة مع المسودة.",
  "daemon.draft_restore_unconfirmed": "لم يؤكد {agent} إعادة المسودة إلى مربع إدخال هذه الجلسة بعدما أرسل {appName} رسالته. يوضع ما كُتب في الجلسة أثناء تنحية المسودة في مربع الإدخال كما هو الآن، ولا تُرسل الرسالة مجدداً. افحص مربع الإدخال قبل إرسال محتوياته.",
  "daemon.typing_held": "لم يصل بعض ما كُتب في هذه الجلسة أثناء كتابة {appName} لرسالة فيها إلى {agent} بعد. يعرض {agent} مربع حوار أو لا يقبل الإدخال. يُكتب ما حُجز بالترتيب بمجرد قبوله الإدخال مجدداً. إذا عرضت الجلسة مربع حوار، فأجب عنه.",
  "daemon.typing_blocked": "وصل جزء فقط من الرسالة المكتوبة في هذه الجلسة إلى مربع إدخالها. لن تُرسل الرسالة مجدداً. يُتخلّص مما كُتب في الجلسة أثناء كتابة الرسالة عندما تكتب مجدداً، ويذهب ما تكتبه بعد ذلك مباشرة إلى {agent}. تنتظر رسائل {appName} الأخرى حتى يُرسل طلب. افحص مربع الإدخال وأزل ما تبقى من الرسالة قبل إرسال طلب.",
  "daemon.typing_lost": "انتهت هذه الجلسة قبل أن يؤكد {agent} إعادة المسودة، لذا فُقد ما كُتب خلالها ولن يُكتب عند استئنافها.",
