  "branchCleanup.group.protectedFolder": { "zero": "أشجار العمل هذه هي مجلدك الرئيسي أو جذر قرص أو تحتوي على بيانات {appName} نفسه، لذا احتُفظ بها:", "one": "شجرة العمل هذه هي مجلدك الرئيسي أو جذر قرص أو تحتوي على بيانات {appName} نفسه، لذا احتُفظ بها:", "two": "أشجار العمل هذه هي مجلدك الرئيسي أو جذر قرص أو تحتوي على بيانات {appName} نفسه، لذا احتُفظ بها:", "few": "أشجار العمل هذه هي مجلدك الرئيسي أو جذر قرص أو تحتوي على بيانات {appName} نفسه، لذا احتُفظ بها:", "many": "أشجار العمل هذه هي مجلدك الرئيسي أو جذر قرص أو تحتوي على بيانات {appName} نفسه، لذا احتُفظ بها:", "other": "أشجار العمل هذه هي مجلدك الرئيسي أو جذر قرص أو تحتوي على بيانات {appName} نفسه، لذا احتُفظ بها:" },
  "branchCleanup.group.projectFolderUnknown": { "zero": "تعذر التحقق مما إذا كانت أشجار العمل هذه مجلدات لمشاريع أخرى أو تحتوي عليها:", "one": "تعذر التحقق مما إذا كانت شجرة العمل هذه مجلد مشروع آخر أو تحتوي عليه:", "two": "تعذر التحقق مما إذا كانت أشجار العمل هذه مجلدات لمشاريع أخرى أو تحتوي عليها:", "few": "تعذر التحقق مما إذا كانت أشجار العمل هذه مجلدات لمشاريع أخرى أو تحتوي عليها:", "many": "تعذر التحقق مما إذا كانت أشجار العمل هذه مجلدات لمشاريع أخرى أو تحتوي عليها:", "other": "تعذر التحقق مما إذا كانت أشجار العمل هذه مجلدات لمشاريع أخرى أو تحتوي عليها:" },
  "branchCleanup.note.projectFolderUnknown": { "zero": "قد تحتوي على ملفات مشروع آخر. عندما تصبح قابلة للقراءة، افحص محتوياتها قبل إزالتها بنفسك.", "one": "قد تحتوي على ملفات مشروع آخر. عندما تصبح قابلة للقراءة، افحص محتوياتها قبل إزالتها بنفسك.", "two": "قد تحتويان على ملفات مشروع آخر. عندما تصبحان قابلتين للقراءة، افحص محتوياتهما قبل إزالتهما بنفسك.", "few": "قد تحتوي على ملفات مشروع آخر. عندما تصبح قابلة للقراءة، افحص محتوياتها قبل إزالتها بنفسك.", "many": "قد تحتوي على ملفات مشروع آخر. عندما تصبح قابلة للقراءة، افحص محتوياتها قبل إزالتها بنفسك.", "other": "قد تحتوي على ملفات مشروع آخر. عندما تصبح قابلة للقراءة، افحص محتوياتها قبل إزالتها بنفسك." },
  "branchCleanup.group.staysUnknown": { "zero": "تبقى أشجار العمل هذه لتعذر التحقق مما إذا كانت مجلدات لمشاريع أخرى أو تحتوي عليها:", "one": "تبقى شجرة العمل هذه لتعذر التحقق مما إذا كانت مجلد مشروع آخر أو تحتوي عليه:", "two": "تبقى أشجار العمل هذه لتعذر التحقق مما إذا كانت مجلدات لمشاريع أخرى أو تحتوي عليها:", "few": "تبقى أشجار العمل هذه لتعذر التحقق مما إذا كانت مجلدات لمشاريع أخرى أو تحتوي عليها:", "many": "تبقى أشجار العمل هذه لتعذر التحقق مما إذا كانت مجلدات لمشاريع أخرى أو تحتوي عليها:", "other": "تبقى أشجار العمل هذه لتعذر التحقق مما إذا كانت مجلدات لمشاريع أخرى أو تحتوي عليها:" },
