  "settings.autoApproveSession.description.on": "يمكن لجلسة بدء جلسة تتبعك دون سؤالك أولاً. لا يملك الجلسة الجديدة أحد غيرك.",
  "settings.autoApproveResume.label": "الموافقة تلقائياً على طلبات الاستئناف",
  "settings.autoApproveResume.description.off": "عند تفعيله، يمكن لجلسة إعادة فتح جلسة أو استئنافها، أو استئناف محادثة في جلسة جديدة، دون سؤالك أولاً. تحتفظ الجلسة المُعاد فتحها أو المستأنفة بمالكها، ويُعاد فتح مالكيها المؤرشفين معها. لا يملك الجلسة الجديدة التي تبدأ بهذه الطريقة أحد غيرك.",
  "settings.autoApproveResume.description.on": "يمكن لجلسة إعادة فتح جلسة أو استئنافها، أو استئناف محادثة في جلسة جديدة، دون سؤالك أولاً. تحتفظ الجلسة المُعاد فتحها أو المستأنفة بمالكها، ويُعاد فتح مالكيها المؤرشفين معها. لا يملك الجلسة الجديدة التي تبدأ بهذه الطريقة أحد غيرك.",
  "settings.autoApproveAccountSwitches.label": "الموافقة تلقائياً على تبديل الحسابات",
