  "settings.autoSwitch.description.on": "تُبدّل الجلسة التي تتوقف عند حد استخدام حسابها إلى حساب آخر لديه استخدام متبقٍ وتتابع العمل.",
  "settings.startQuotaWindows.label": "بدء فترات الاستخدام تلقائياً",
  "settings.startQuotaWindows.description.off": "عند تفعيله، يبدأ عد فترة الاستخدام فور إعادة تعيينها. يستهلك هذا جزءاً بسيطاً من حدود استخدام الحساب.",
  "settings.startQuotaWindows.description.on": "يبدأ عد فترة الاستخدام فور إعادة تعيينها. يستهلك هذا جزءاً بسيطاً من حدود استخدام الحساب.",
  "settings.startQuotaWindows.help": "حول بدء فترات الاستخدام تلقائياً",
  "settings.startQuotaWindows.helpText": "لا يبدأ عد فترة الاستخدام المُعاد تعيينها حتى الطلب التالي للحساب؛ وحتى ذلك الحين لا يظهر عد تنازلي، وكلما طال الانتظار تأخرت إعادة التعيين التالية. عند تفعيل هذا، يُرسل طلب صغير واحد على ذلك الحساب بأرخص نموذج للوكيل لبدئها.",
  "settings.background.label": "مواصلة العمل في الخلفية عند إغلاق النافذة",
