  "settings.gitWorkflow.development.description.inPlaceWithPreparation": "تعمل جلسة المشروع مباشرة على الفرع الحالي دون قاعدة للفروع أو أشجار العمل. ينطبق التغيير على الجلسات التي تبدأ بعده فقط. تظهر خيارات دمج الإيداعات وإعادة التأسيس والتسليم عندما تعمل الجلسات على فروع خاصة بها.",
  "settings.gitWorkflow.development.description.branch": "يُطلب من جلسة المشروع إنشاء فرع خاص بها في مجلد المشروع قبل تغيير الملفات. يشارك الفرع ذلك المجلد، لذا يناسب هذا جلسة واحدة في المرة. ينطبق التغيير على الجلسات التي تبدأ بعده فقط، وتكون الأولوية لقواعد المشروع الخاصة بالفروع وأشجار العمل.",
  "settings.gitWorkflow.development.description.worktree": "يُطلب من جلسة المشروع إنشاء فرع وشجرة عمل خاصين بها قبل تغيير الملفات. ينطبق التغيير على الجلسات التي تبدأ بعده فقط، وتكون الأولوية لقواعد المشروع الخاصة بالفروع وأشجار العمل.",
  "settings.gitWorkflow.squash.label": "دمج الإيداعات في إيداع واحد قبل التسليم",
  "settings.gitWorkflow.squash.description.off": "عند تفعيله، تُدمج إيداعات كل ميزة في إيداع واحد قبل الدمج أو الدفع أو فتح طلب سحب. يحتفظ إصلاح خطأ غير مرتبط بإيداع خاص به. تنطبق التغييرات على الجلسات التي تبدأ لاحقاً فقط، وتكون الأولوية لقواعد المشروع.",
  "settings.gitWorkflow.squash.description.on": "تُدمج إيداعات كل ميزة في إيداع واحد قبل الدمج أو الدفع أو فتح طلب سحب. يحتفظ إصلاح خطأ غير مرتبط بإيداع خاص به. تنطبق التغييرات على الجلسات التي تبدأ لاحقاً فقط، وتكون الأولوية لقواعد المشروع.",
  "settings.gitWorkflow.rebaseBeforeDelivery.label": "إعادة التأسيس قبل التسليم",
  "settings.gitWorkflow.rebaseBeforeDelivery.description.off": "عند تفعيله، يُعاد تأسيس الفرع على فرعه الهدف قبل تسليم العمل المكتمل بالدمج أو الدفع أو طلب سحب. ينطبق التغيير على الجلسات التي تبدأ بعده فقط، وتكون الأولوية لقواعد المشروع الخاصة.",
  "settings.gitWorkflow.rebaseBeforeDelivery.description.on": "يُعاد تأسيس الفرع على فرعه الهدف قبل تسليم العمل المكتمل بالدمج أو الدفع أو طلب سحب. ينطبق التغيير على الجلسات التي تبدأ بعده فقط، وتكون الأولوية لقواعد المشروع الخاصة.",
