  "settings.gitWorkflow.revertGate.description.on": "يُحظر في جلسة المشروع تحديث الفرع الذي يلغي بصمت تغييرات موجودة بالفعل على فرعه الهدف. يسري التغيير فوراً، بما في ذلك الجلسات العاملة.",
